quested');\n\nINSERT INTO quotes(shipment_id,driver_id,price,notes,status) VALUES\n(1,(SELECT id FROM users WHERE email='driver.delta@example.com'),1100,'Can pick up by 9am','Pending'),\n(1,(SELECT id FROM users WHERE email='driver.echo@example.com'),1300,'Reefer available','Pending');\n\nINSERT INTO invoices(user_id,plan,amount,status,due_date) VALUES\n((SELECT id FROM users WHERE email='driver.delta@example.com'),'Driver Pro',49,'Unpaid',date('now','+7 days')),\n((SELECT id FROM users WHERE email='driver.echo@example.com'),'Driver Pro',49,'PastDue',date('now','-2 days')),\n((SELECT id FROM users WHERE email='alice@example.com'),'Customer Basic',0,'Paid',date('now'));\n